        if(ts==null){
            continue;
        }
        if(timeRanges==null || timeRanges.isEmpty()){
            snapshots.add(ts);
            continue;
        }
        long tsTime = ts.getTimestamp();
        for(ProfileAnalyzeTimeRange range : timeRanges){
            if(range == null){
                continue;
            }
            long start=range.getStart();
            long end=range.getEnd();
            if(tsTime >= start && tsTime <= end){
                snapshots.add(ts);
                break;
            }
        }
    }
    reader.close();
    return snapshots;
}

